from pathlib import Path
import json

target = Path.home()/'.local/state/prediction-project-executor'/'DEV-PRED-CANDIDATE-INVENTORY-20261005-E001.json'
if not target.is_file() or target.is_symlink():
    print('INVENTORY_DETAIL missing_executor_result', flush=True)
    raise SystemExit(1)

data = json.loads(target.read_text())

hits=[]
def walk(x):
    if isinstance(x, dict):
        for v in x.values(): walk(v)
    elif isinstance(x, list):
        for v in x: walk(v)
    elif isinstance(x, str) and 'CANDIDATE_INVENTORY ' in x:
        hits.append(x)

walk(data)
if not hits:
    print('INVENTORY_DETAIL no_payload topkeys='+','.join(sorted(data.keys())), flush=True)
    raise SystemExit(2)

line=hits[-1]
payload=line.split('CANDIDATE_INVENTORY ',1)[1].strip()
# tolerate stdout wrappers / trailing lines
if '\n' in payload:
    payload=payload.splitlines()[0]
obj=json.loads(payload)
print('INVENTORY_DETAIL '+json.dumps(obj,separators=(',',':'),default=str),flush=True)
